349	                forward_declare_functions_with_prefix(ctx, mod_decls, prefix)
350	            },
351	            HDecl::ExternType { .. } => {},
352	            HDecl::TypeAlias { .. } => {},
353	            HDecl::Const { name, .. } => {
354	                // Forward-declare const as a zero-arg function (lazy getter)
